def check(N, d):
    for s in range(N + 1):
        for k in range(s + 2, N - s + 1):
            dp = [[float('inf')] * (N - s + 1) for _ in range(k + 1)]
            dp[0][0] = 0
            for i in range(k):
                for j in range(N - s + 1):
                    if dp[i][j] == float('inf'): continue
                    for n_i in range(1, N - s - j + 1, 2):
                        lower = n_i * (d - n_i + 1)
                        min_e = max(0, lower)
                        if (min_e % 2) != (n_i * d % 2):
                            min_e += 1
                        if min_e <= n_i * s:
                            dp[i+1][j+n_i] = min(dp[i+1][j+n_i], dp[i][j] + min_e)
            for j in range(N - s + 1):
                if dp[k][j] <= s * d:
                    return True
    return False

